import{_ as t,a as e,b as o,c as r,e as d,d as l}from"./chunks/ee-ohos-12.YBQ8g5AA.js";import{_ as i}from"./chunks/ee-ohos-2.C7lmEPa0.js";import{_ as n,o as s,c,a3 as v}from"./chunks/framework.BveOjhN0.js";const f=JSON.parse('{"title":"简介","description":"","frontmatter":{"title":"简介"},"headers":[],"relativePath":"zh/11.harmonyos/00.introduction.md","filePath":"zh/11.harmonyos/00.introduction.md","lastUpdated":1783502384000}'),p={name:"zh/11.harmonyos/00.introduction.md"};function g(m,a,h,b,u,_){return s(),c("div",null,[...a[0]||(a[0]=[v('<div class="hero" data-v-36078452><div class="hero-badges" data-v-36078452><span class="badge badge--star" data-v-36078452>⭐ 8000+ Star</span><span class="badge badge--version" data-v-36078452>🚀 v5</span><span class="badge badge--ohos" data-v-36078452>🪶 鸿蒙 HarmonyOS</span></div><h1 class="hero-title" data-v-36078452>ElectronEgg: 全新升级v5 - 轻松开发鸿蒙应用</h1><div class="hero-actions" data-v-36078452><a class="btn btn--primary" href="https://gitcode.com/dromara/electron-egg" target="_blank" rel="noopener" data-v-36078452>GitCode 仓库 →</a><a class="btn btn--primary" href="https://gitee.com/dromara/electron-egg" target="_blank" rel="noopener" data-v-36078452>Gitee 仓库 →</a><a class="btn btn--primary" href="https://github.com/dromara/electron-egg" target="_blank" rel="noopener" data-v-36078452>GitHub 仓库 →</a></div></div><blockquote data-v-36078452><p data-v-36078452>一套代码，打包 Windows、Mac、Linux，现在还能直接跑在鸿蒙（HarmonyOS）上。ElectronEgg v5 带着鸿蒙支持来了。</p></blockquote><h2 id="写在前面" tabindex="-1" data-v-36078452>写在前面 <a class="header-anchor" href="#写在前面" aria-label="Permalink to &quot;写在前面&quot;" data-v-36078452>​</a></h2><p data-v-36078452><a href="https://gitcode.com/dromara/electron-egg" target="_blank" rel="noreferrer" data-v-36078452>ElectronEgg</a> 自开源以来，一直的愿景很简单：<strong data-v-36078452>让所有开发者都能学会桌面软件研发</strong>。它把前端、服务端的工程化思维带进桌面开发，用一套清晰的 controller / service / preload 分层架构，把 Electron 的复杂度封装起来。目前框架在全网「gitee、github」已累计 <strong data-v-36078452>8000+ Star</strong>，经过大量团队长期实践验证，请放心使用。</p><p data-v-36078452>v5 版本在此基础上完成了一次全新升级，最重磅的能力之一，就是——<strong data-v-36078452>轻松开发鸿蒙应用</strong>。</p><p data-v-36078452>经过不断尝试，终于把 ElectronEgg 运行在鸿蒙设备上，虽然现在是<strong data-v-36078452>测试阶段</strong>，但已经跑通了整个流程，效果图见下方。</p><h2 id="鸿蒙支持-一套代码-跑在-harmonyos-上" tabindex="-1" data-v-36078452>鸿蒙支持：一套代码，跑在 HarmonyOS 上 <a class="header-anchor" href="#鸿蒙支持-一套代码-跑在-harmonyos-上" aria-label="Permalink to &quot;鸿蒙支持：一套代码，跑在 HarmonyOS 上&quot;" data-v-36078452>​</a></h2><p data-v-36078452>过去，把 Electron 应用搬到鸿蒙上几乎是一件&quot;重新写一遍&quot;的事。v5 会把资源应用到 HarmonyOS HAP 中，由 HAP 工程的 web 引擎加载。<strong data-v-36078452>你现有的 ElectronEgg 业务代码，几乎不用改，就能以鸿蒙应用的形式运行。</strong></p><p data-v-36078452>下面是 ElectronEgg 的 demo 应用在 HarmonyOS 上的真实运行效果：</p><blockquote data-v-36078452><p data-v-36078452>应用已安装到鸿蒙系统中</p></blockquote><div class="center-logo" data-v-36078452><img src="'+t+'" alt="logo" data-v-36078452></div><p data-v-36078452><img src="'+e+'" alt="ElectronEgg demo 在鸿蒙应用中心" data-v-36078452></p><blockquote data-v-36078452><p data-v-36078452>应用启动</p></blockquote><p data-v-36078452><img src="'+i+'" alt="ElectronEgg demo 启动" data-v-36078452></p><blockquote data-v-36078452><p data-v-36078452>框架功能演示：通信、控制器、服务等能力在鸿蒙端正常工作</p></blockquote><p data-v-36078452><img src="'+o+'" alt="ElectronEgg demo 功能演示" data-v-36078452></p><blockquote data-v-36078452><p data-v-36078452>加载本地图片功能演示</p></blockquote><p data-v-36078452><img src="'+r+'" alt="ElectronEgg demo 功能演示" data-v-36078452></p><blockquote data-v-36078452><p data-v-36078452>加载web页面功能演示</p></blockquote><p data-v-36078452><img src="'+d+'" alt="ElectronEgg demo 功能演示" data-v-36078452></p><blockquote data-v-36078452><p data-v-36078452>dock 栏功能演示</p></blockquote><p data-v-36078452><img src="'+l+'" alt="ElectronEgg demo 功能演示" data-v-36078452></p><p data-v-36078452>可以看到，原本在 Windows / Mac 上运行的桌面应用，在鸿蒙端从安装到各项功能都跑得很顺畅。这就是 v5 鸿蒙支持想表达的核心：<strong data-v-36078452>跨端不再是口号，鸿蒙是一等公民。</strong></p><h2 id="v5-还升级了什么" tabindex="-1" data-v-36078452>v5 还升级了什么 <a class="header-anchor" href="#v5-还升级了什么" aria-label="Permalink to &quot;v5 还升级了什么&quot;" data-v-36078452>​</a></h2><p data-v-36078452>除了鸿蒙支持，v5 对框架内核做了一次较为彻底的重构：</p><ul data-v-36078452><li data-v-36078452>TypeScript 全面重构：所有 API 均有完整类型定义。</li><li data-v-36078452>双模块格式输出：同时支持 CJS 和 ESM 两种格式。</li><li data-v-36078452>Pino 日志体系：更强大的日志记录功能。</li><li data-v-36078452>Bundle 注册表机制：启动更快。</li><li data-v-36078452>主进程打包： 主进程代码可以像前端 bundle 。</li><li data-v-36078452>构建配置全面增强：新增大量精细控制项。</li><li data-v-36078452>加密系统升级： 更安全。</li><li data-v-36078452>ee-bin 全面升级：新增完整 TypeScript 类型体系。</li></ul><h2 id="谁适合用" tabindex="-1" data-v-36078452>谁适合用 <a class="header-anchor" href="#谁适合用" aria-label="Permalink to &quot;谁适合用&quot;" data-v-36078452>​</a></h2><ul data-v-36078452><li data-v-36078452>想用前端技术栈（Vue / React / HTML）做桌面软件的开发者</li><li data-v-36078452>需要把内部工具、管理后台、办公软件交付为桌面应用团队</li><li data-v-36078452>要同时覆盖 Windows、Mac、Linux，<strong data-v-36078452>以及鸿蒙</strong>的产品</li><li data-v-36078452>希望降低 Electron 上手成本、想要一套清晰架构的团队</li></ul><p data-v-36078452>无论你是前端、服务端、运维还是客户端开发者，都能很快入门。</p><h2 id="写在最后" tabindex="-1" data-v-36078452>写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;" data-v-36078452>​</a></h2><p data-v-36078452>桌面软件（办公方向、个人工具）仍然是未来十几年 PC 端的刚需之一。ElectronEgg 想做的，是让这件事变得简单——而现在，这份&quot;简单&quot;也延伸到了鸿蒙。</p><p data-v-36078452>框架已广泛应用于记账、政务、企业、医疗、学校、股票交易、ERP、娱乐、视频等领域的客户端，欢迎放心使用。</p><div class="tip custom-block" data-v-36078452><p class="custom-block-title" data-v-36078452>开源与社区</p><ul data-v-36078452><li data-v-36078452>GitCode：<a href="https://gitcode.com/dromara/electron-egg" target="_blank" rel="noreferrer" data-v-36078452>https://gitcode.com/dromara/electron-egg</a></li><li data-v-36078452>Gitee：<a href="https://gitee.com/dromara/electron-egg" target="_blank" rel="noreferrer" data-v-36078452>https://gitee.com/dromara/electron-egg</a></li><li data-v-36078452>GitHub：<a href="https://github.com/dromara/electron-egg" target="_blank" rel="noreferrer" data-v-36078452>https://github.com/dromara/electron-egg</a></li></ul></div><p data-v-36078452>如果对你有帮助，欢迎 Star 支持，也欢迎加入社区一起交流。</p>',34)])])}const S=n(p,[["render",g],["__scopeId","data-v-36078452"]]);export{f as __pageData,S as default};
